CREATE DATABASE IF NOT EXISTS sevasetu CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE sevasetu;
CREATE TABLE users (id CHAR(36) PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(20), password_hash VARCHAR(255) NOT NULL, role ENUM('CITIZEN','ADMIN','OFFICER','SUPER_ADMIN') NOT NULL DEFAULT 'CITIZEN', address VARCHAR(255), city VARCHAR(100), state VARCHAR(100), pincode VARCHAR(10), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_users_role(role));
CREATE TABLE departments (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT, contact_email VARCHAR(255), contact_phone VARCHAR(20), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE complaints (id CHAR(36) PRIMARY KEY, complaint_number VARCHAR(30) NOT NULL UNIQUE, citizen_id CHAR(36) NOT NULL, department_id CHAR(36), title VARCHAR(200) NOT NULL, description TEXT NOT NULL, category ENUM('ROADS','GARBAGE','WATER','DRAINAGE','ELECTRICITY','STREET_LIGHT','PUBLIC_PROPERTY','TRAFFIC','SANITATION','OTHER') NOT NULL DEFAULT 'OTHER', subcategory VARCHAR(120), latitude DECIMAL(10,7), longitude DECIMAL(10,7), address VARCHAR(255), city VARCHAR(100), state VARCHAR(100), pincode VARCHAR(10), severity ENUM('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL DEFAULT 'MEDIUM', priority ENUM('LOW','MEDIUM','HIGH','URGENT') NOT NULL DEFAULT 'MEDIUM', status ENUM('SUBMITTED','UNDER_REVIEW','ASSIGNED','IN_PROGRESS','RESOLVED','REJECTED','REOPENED') NOT NULL DEFAULT 'SUBMITTED', ai_category VARCHAR(50), ai_confidence DECIMAL(5,4), ai_priority VARCHAR(20), ai_summary TEXT, assigned_officer_id CHAR(36), resolved_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT fk_complaint_citizen FOREIGN KEY(citizen_id) REFERENCES users(id), CONSTRAINT fk_complaint_department FOREIGN KEY(department_id) REFERENCES departments(id), CONSTRAINT fk_complaint_officer FOREIGN KEY(assigned_officer_id) REFERENCES users(id), INDEX idx_complaints_citizen(citizen_id), INDEX idx_complaints_department(department_id), INDEX idx_complaints_officer(assigned_officer_id), INDEX idx_complaints_status(status), INDEX idx_complaints_category(category), INDEX idx_complaints_priority(priority), INDEX idx_complaints_created(created_at));
CREATE TABLE complaint_status_history (id CHAR(36) PRIMARY KEY, complaint_id CHAR(36) NOT NULL, old_status VARCHAR(30), new_status VARCHAR(30) NOT NULL, changed_by CHAR(36) NOT NULL, remarks TEXT, created_at DATETIME NOT NULL, CONSTRAINT fk_history_complaint FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE, CONSTRAINT fk_history_user FOREIGN KEY(changed_by) REFERENCES users(id), INDEX idx_history_complaint(complaint_id));
CREATE TABLE complaint_images (id CHAR(36) PRIMARY KEY, complaint_id CHAR(36) NOT NULL, file_name VARCHAR(255) NOT NULL, file_path VARCHAR(500) NOT NULL, mime_type VARCHAR(100) NOT NULL, file_size INT NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_image_complaint FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE, INDEX idx_images_complaint(complaint_id));
CREATE TABLE notifications (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, complaint_id CHAR(36), title VARCHAR(200) NOT NULL, message TEXT NOT NULL, type VARCHAR(50) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL, CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_notification_complaint FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE SET NULL, INDEX idx_notifications_user(user_id));
CREATE TABLE refresh_tokens (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, revoked_at DATETIME, replaced_by_token_id CHAR(36), created_at DATETIME NOT NULL, CONSTRAINT fk_refresh_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_refresh_replaced FOREIGN KEY(replaced_by_token_id) REFERENCES refresh_tokens(id), INDEX idx_refresh_user(user_id), INDEX idx_refresh_expires(expires_at));
